function placeNavIndicator(){const tab=root.querySelector('nav .active');if(tab)phone.style.setProperty('--nav-x',(tab.offsetLeft+tab.offsetWidth/2-22)+'px')}
function filterMemories(){const q=(state.query||'').trim(),kind=state.filter||'全部';let count=0;root.querySelectorAll('.memory').forEach(n=>{n.hidden=!(n.textContent.includes(q)&&(kind==='全部'||n.dataset.kind===kind));if(!n.hidden)count++});const empty=root.querySelector('.empty-search');if(empty)empty.hidden=count>0;root.querySelector('.search-region')?.classList.toggle('has-query',q.length>0)}
function compactAudio(){return `<div class="audio-row"><button data-action="play" aria-label="演示播放状态">${icon('play')}</button><div class="wave" aria-hidden="true">${wave()}</div><span class="time">0:12</span></div>`}
function taskRow(id,title,when=''){state.checked??={};const done=!!state.checked[id];return `<div class="task ${done?'done':''}"><button class="check" data-task-id="${id}" aria-label="${done?'撤销完成':'完成'}${safe(title)}" aria-pressed="${done}">${icon('check')}</button><button class="task-copy" data-action="task-detail"><span class="title">${safe(title)}</span>${when?`<span class="task-time">${when}</span>`:''}</button></div>`}
function updateSubmit(){const button=sheet.querySelector('[data-action="save"],[data-action="save-task"]'),field=sheet.querySelector('textarea');if(button&&field)button.disabled=!field.value.trim()||button.dataset.busy==='true'}
function render(){
 stop();phone.dataset.page=page;state.selectedDay??=4;state.query??='';state.filter??='全部';
 root.querySelector('.brand').textContent=page==='now'?'爱忆':page==='memories'?'回忆':'待办';
 if(page==='now')main.innerHTML=`<div class="welcome-strip"><div><p class="welcome-date">11 月 04 日 · 星期三</p><h1>今天，慢慢记。</h1></div><button class="lulu-ref" data-action="companion" aria-label="打开噜噜陪伴，角色暂用原版参考"></button></div><section class="feed" aria-label="今天的记录"><div class="section-line"><h2>今天的片刻</h2></div>${state.added.map(t=>`<article class="entry"><button class="read" data-action="detail"><h2>${safe(t)}</h2></button></article>`).join('')}<article class="entry"><button class="read" data-action="detail"><h2>路过花店，带了一束洋桔梗</h2><p>奶白色的花瓣，像今天傍晚的云。<br>放在书桌边，心情也变得轻了一点。</p></button></article><article class="entry"><h2>给周末留一个小计划</h2>${compactAudio()}</article></section><div class="composer"><button data-action="write">${state.draft?safe(state.draft):'这一刻，想记下什么？'}</button><div class="composer-foot"><div class="composer-tools"><button data-action="attach" aria-label="添加照片">${icon('image')}</button><button data-action="audio" aria-label="音频附件">${icon('mic')}</button></div><button data-action="write" class="edit-entry" aria-label="展开记录编辑">${icon('square-pen')}</button></div></div>`;
 else if(page==='memories')main.innerHTML=`<div class="search-region"><div class="search">${icon('search')}<input aria-label="搜索回忆" placeholder="找一句话、一件小事…" value="${safe(state.query)}"><button data-action="filters" aria-label="筛选">${icon('sliders-horizontal')}</button></div><div class="search-actions"><button data-action="ask">${icon('sparkles')}问一问</button><button data-action="more">${icon('folder-open')}回忆工具</button></div></div><div class="filterline">${[['全部','全部'],['收藏','收藏'],['图片','图片'],['原音','音频']].map(([kind,label])=>`<button class="${state.filter===kind?'selected':''}" data-filter="${kind}" aria-pressed="${state.filter===kind}">${label}</button>`).join('')}</div><section class="memory-list" aria-label="记录列表"><h2 class="date-group">11 月 4 日 · 周三</h2><article class="memory" data-kind="收藏"><div class="copy"><button data-action="detail" class="memory-open"><h2>路过花店，带了一束洋桔梗</h2><p>奶白色的花瓣，像今天傍晚的云。</p></button><time class="record-time">16:24</time></div></article><article class="memory" data-kind="原音"><div class="copy"><h2>给周末留一个小计划</h2>${compactAudio()}<time class="record-time">12:08</time></div></article><h2 class="date-group">11 月 2 日 · 周一</h2><article class="memory" data-kind="收藏"><div class="copy"><button data-action="detail" class="memory-open"><h2>原来慢一点也没有关系</h2><p>今天读到的一句话，想留给以后的自己。</p></button><time class="record-time">21:16</time></div></article><p class="empty-search" hidden>没有找到记录</p></section>`;
 else main.innerHTML=`<div class="week" aria-label="选择日期">${['一','二','三','四','五','六','日'].map((d,i)=>`<button class="day ${state.selectedDay===i+2?'current':''}" data-day="${i+2}" aria-pressed="${state.selectedDay===i+2}"><small>${d}</small>${i+2}</button>`).join('')}</div><section class="task-list" aria-label="待办列表"><div class="section-line"><h2>${state.selectedDay===4?'今天':`11 月 ${state.selectedDay} 日 · 周${['一','二','三','四','五','六','日'][state.selectedDay-2]}`}</h2></div>${(state.extraTasks||[]).filter(t=>t.day===state.selectedDay).map(t=>taskRow(t.id,t.title)).join('')}${state.selectedDay===4?taskRow('photos','整理旅行照片','19:00 <span aria-label="已安排提醒">'+icon('bell')+'</span>')+taskRow('book','读完手边的那本书')+`<div class="section-line upcoming"><h2>接下来</h2></div>`+taskRow('walk','去公园走走','11 月 7 日'):state.selectedDay===7?taskRow('walk','去公园走走'):(state.extraTasks||[]).some(t=>t.day===state.selectedDay)?'':'<p class="empty-search">这一天还没有安排</p>'}<button class="suggestion" data-action="proposal"><span>待确认草稿</span>${icon('chevron-right')}</button></section><button class="add-task" data-action="new-task">${icon('plus')}添加待办</button>`;
 main.classList.remove('enter');void main.offsetWidth;main.classList.add('enter');root.querySelectorAll('[data-page]').forEach(b=>{const active=b.dataset.page===page;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});icons();filterMemories();requestAnimationFrame(placeNavIndicator);
}
